import sys

def girth(n, adj):
    best = sys.maxsize
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        q = [s]
        for u in q:
            for w in adj[u]:
                if dist[w] == -1:
                    dist[w] = dist[u] + 1
                    parent[w] = u
                    q.append(w)
                elif parent[u] != w and parent[w] != u:
                    # found a cycle
                    cycle_len = dist[u] + dist[w] + 1
                    if cycle_len < best:
                        best = cycle_len
    return best if best != sys.maxsize else -1

