# Check 3-colorability via brute force (2^21 is too big, but we can use backtracking)
def is_3_colorable(n, adj):
    colors = [-1]*n
    def dfs(v):
        if v == n:
            return True
        for c in range(3):
            ok = True
            for w in adj[v]:
                if colors[w] == c:
                    ok = False
                    break
            if ok:
                colors[v] = c
                if dfs(v+1):
                    return True
                colors[v] = -1
        return False
